_MATRIX_BUNDLE_DIFF_KEYS = {"before", "after"}
_MATRIX_BUNDLE_EVOLUTION_KEYS = {"stages"}
_EVOLUTION_CHECKPOINT_KEYS = {"report", "start", "end"}
_LEDGER_KEYS = {"report"}
_VERIFY_KEYS = {"report", "expected"}
